package com.allianz.pac.baseservice.mapper;

import com.allianz.pac.baseservice.dto.request.CustomerRequest;
import com.allianz.pac.baseservice.dto.response.CustomerResponse;
import com.allianz.pac.baseservice.model.Customer;
import org.mapstruct.Mapper;
import org.mapstruct.Mapping;
import org.mapstruct.MappingTarget;

/**
 * Maps between customer DTOs and the {@link Customer} entity (implementation generated by
 * MapStruct at compile time; unmapped target properties fail the build).
 */
@Mapper
public interface CustomerMapper {

    /**
     * Creates a new entity from a request. Identity, audit and version fields are managed by JPA.
     *
     * @param request customer request
     * @return new, unsaved entity
     */
    @Mapping(target = "id", ignore = true)
    @Mapping(target = "createdAt", ignore = true)
    @Mapping(target = "createdBy", ignore = true)
    @Mapping(target = "updatedAt", ignore = true)
    @Mapping(target = "updatedBy", ignore = true)
    @Mapping(target = "version", ignore = true)
    Customer toEntity(CustomerRequest request);

    /**
     * Converts an entity into the API representation.
     *
     * @param customer entity
     * @return customer response
     */
    CustomerResponse toResponse(Customer customer);

    /**
     * Copies the request values onto an existing entity (full update).
     *
     * @param request  customer request
     * @param customer entity to update
     */
    @Mapping(target = "id", ignore = true)
    @Mapping(target = "createdAt", ignore = true)
    @Mapping(target = "createdBy", ignore = true)
    @Mapping(target = "updatedAt", ignore = true)
    @Mapping(target = "updatedBy", ignore = true)
    @Mapping(target = "version", ignore = true)
    void updateEntity(CustomerRequest request, @MappingTarget Customer customer);
}
